import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate that a string is a valid date in YYYY-MM-DD format.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!match) return false;
  const date = new Date(dateStr);
  if (!(date instanceof Date) || isNaN(date.getTime())) return false;
  const [_, year, month, day] = match;
  return date.getUTCFullYear() === parseInt(year) &&
         date.getUTCMonth() + 1 === parseInt(month) &&
         date.getUTCDate() === parseInt(day);
}

/**
 * Validate that a discount percent is between 0 and 100.
 * @param {number} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customer = getCustomer(customerId);
  if (!customer.ok) return customer;

  const tierDiscount = TIER_DISCOUNTS[customer.value.tier] ?? 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) return product;

    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  return Math.max(0, lineTotal(line) * line.discountPercent / 100);
}

/**
 * Calculate the VAT for a single line: VAT is on the amount after discount, rounded per line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number} VAT in cents
 */
export function lineVat(line) {
  const vatRate = line.vatRate ?? 0;
  if (vatRate === 0) return 0;
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  const vat = amountAfterDiscount * vatRate / 100;
  return Math.max(0, roundCents(vat));
}

/**
 * Calculate the totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = subtotal - discount + vat;
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    total: Math.max(0, total),
  };
}

/**
 * Add or increment a line on a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} newLine
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const product = getProduct(sku);
  if (!product.ok) return product;

  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  const tierDiscount = TIER_DISCOUNTS[customer.value.tier] ?? 0;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLine = newLines.find((line) => line.sku === sku);

  if (existingLine) {
    existingLine.qty += qty;
    if (discountPercent !== undefined) {
      existingLine.discountPercent = discountPercent;
    }
  } else {
    const lineDiscount = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku,
      name: product.value.name,
      qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent: lineDiscount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to issued.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of existing invoice numbers
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

