test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
      { qty: 3, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2 * 8500 + 1 * 9500 + 3 * 6000);
  assert.equal(totals.subtotal, 44500);
});

test('invoiceTotals sets total equal to subtotal', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals handles empty invoice', () => {
