      { qty: 1, unitPrice: 37 },
      { qty: 2, unitPrice: 249 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 37 + 2 * 249);
  assert.equal(totals.total, 535);
});

test('lineDiscount calculates discount as lineTotal * discountPercent / 100', () => {
  const line = { qty: 2, unitPrice: 8500, discountPercent: 10 };
  const discount = lineDiscount(line);
  assert.equal(discount, 1700);
});

test('lineDiscount returns 0 for no discount', () => {
  const line = { qty: 2, unitPrice: 8500 };
