});

test('lineDiscount handles decimal discount percentages', () => {
  const line = { qty: 1, unitPrice: 10000, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  assert.equal(discount, 1250);
});

test('lineDiscount handles 100% discount', () => {
  const line = { qty: 2, unitPrice: 8500, discountPercent: 100 };
  const discount = lineDiscount(line);
  assert.equal(discount, 17000);
});

test('invoiceTotals with discount returns subtotal, discount, and total', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.total, 15300);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 8500, discountPercent: 10 },
      { qty: 1, unitPrice: 9500, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 18000);
  assert.equal(totals.discount, 850 + 1900);
  assert.equal(totals.total, 18000 - 2750);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 15 }],
