  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10000 - 1000 + 1890);
});

test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 2100 + 900);
  assert.equal(totals.total, 20000 + 3000);
});

test('invoiceTotals with mixed VAT rates and discounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 17000;
  const line1Discount = 1700;
  const line1Vat = Math.round((line1Total - line1Discount) * 21 / 100 * 1e6) / 1e6;
  const line2Vat = Math.round(10000 * 9 / 100 * 1e6) / 1e6;
  assert.equal(totals.subtotal, 27000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.vat, line1Vat + line2Vat);
  assert.equal(totals.total, 27000 - 1700 + (line1Vat + line2Vat));
});

